import { MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry, DirectionalLight, AmbientLight } = ctx.THREE;

  // 1. Root group
  const root = new Group();

  // Keep track of active systems for cleanup
  const activeTimelines = [];
  const activePrimitives = [];

  // 2. STAGE BACKDROP (Fills the ~7x6 region at z = -2.5 to avoid FLAT_VOID)
  const colors = config.intent?.visualSpec?.colors ?? config.colors ?? {
    ink: "#16161d",
    paper: "#e8ecf2",
    accent: "#ff2a38",
    surface: "#0b0b10"
  };

  const backdropGeo = new PlaneGeometry(8, 7);
  // Machined-metal look visual backdrop with high roughness, low metalness
  const backdropMat = new MeshStandardNodeMaterial({
    color: colors.surface,
    roughness: 0.8,
    metalness: 0.2
  });
  const backdrop = new Mesh(backdropGeo, backdropMat);
  backdrop.position.set(0, 0, -2.5);
  root.add(backdrop);

  // 3. CONTACT SHADOW under the main subject
  const shadowGeo = new PlaneGeometry(2.5, 2.5);
  const shadowMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    transparent: true,
    opacity: 0.5,
    roughness: 1.0,
    metalness: 0.0,
    depthWrite: false
  });
  const shadowPlane = new Mesh(shadowGeo, shadowMat);
  shadowPlane.rotation.x = -Math.PI / 2;
  shadowPlane.position.set(0, -1.2, 0.2);
  root.add(shadowPlane);

  // 4. LOCAL LIGHTING (Rim/Back Accent)
  // An accent rim light to represent the "accent rim light" effects directive
  const rimLight = new DirectionalLight(colors.accent, 1.4);
  rimLight.position.set(-2, 2, -1);
  root.add(rimLight);

  // Soft fill
  const localFill = new AmbientLight(colors.paper, 0.4);
  root.add(localFill);

  // 5. THE HERO MESH (Gear A from the spec)
  const meshContainer = new Group();
  root.add(meshContainer);

  let loadedMesh = null;

  if (config.meshUrl) {
    ctx.glbLoader.loadGLB(config.meshUrl).then((gltf) => {
      loadedMesh = gltf.scene;

      // Apply Machined-metal PBR settings to child meshes
      loadedMesh.traverse((child) => {
        if (child.isMesh) {
          child.castShadow = true;
          child.receiveShadow = true;

          if (child.material) {
            // Apply physical properties based on the spec
            child.material.roughness = 0.52;
            child.material.metalness = 0.55;
            if (typeof child.material.clearcoat !== 'undefined') {
              child.material.clearcoat = 0.2;
            }
          }
        }
      });

      // Fit and center
      loadedMesh.scale.setScalar(1.5);
      loadedMesh.position.set(0, 0, 0);
      meshContainer.add(loadedMesh);

      // Settle animation once loaded
      gsap.fromTo(meshContainer.scale, 
        { x: 0.1, y: 0.1, z: 0.1 },
        { x: 1, y: 1, z: 1, duration: 0.9, ease: 'power4.out' }
      );
    }).catch((err) => {
      console.warn("Failed loading mesh:", err);
    });
  }

  // 6. CAPTION STRIP / DECORATIVE ACCENT (Underneath the model)
  const captionBgGeo = new PlaneGeometry(2.0, 0.35);
  const captionBgMat = new MeshStandardNodeMaterial({
    color: colors.ink,
    roughness: 0.6,
    metalness: 0.5
  });
  const captionStrip = new Mesh(captionBgGeo, captionBgMat);
  captionStrip.position.set(0, -1.3, 0.3);
  root.add(captionStrip);

  // Caption text element (Mono styling as requested in display guidelines)
  const captionText = ctx.fontAtlas.createText("GEAR SYSTEM // 01", {
    fontSize: 0.08,
    color: colors.paper,
    align: 'center'
  });
  captionText.position.set(0, -1.3, 0.32);
  root.add(captionText);

  // Accent signal pip (10% or less accent coverage)
  const pipGeo = new PlaneGeometry(0.06, 0.06);
  const pipMat = new MeshStandardNodeMaterial({
    color: colors.accent,
    roughness: 0.2,
    emissive: colors.accent,
    emissiveIntensity: 1.2
  });
  const pip = new Mesh(pipGeo, pipMat);
  pip.position.set(-0.75, -1.3, 0.33);
  root.add(pip);

  // 7. CINEMATIC PRIMITIVES
  if (config.cinematicPrimitives) {
    config.cinematicPrimitives.forEach((prim) => {
      if (ctx.primitives[prim.name]) {
        const result = ctx.primitives[prim.name](meshContainer, prim.params);
        if (result) {
          activePrimitives.push(result);
        }
      }
    });
  }

  // Fallback defaults if config primitives were missing but specified in prompt
  if (activePrimitives.length === 0) {
    const p1 = ctx.primitives['parallax-scroll']?.(meshContainer, { intensity: 0.4 });
    if (p1) activePrimitives.push(p1);
    const p2 = ctx.primitives['magnetic-cursor']?.(meshContainer, { radius: 1.2, strength: 0.35 });
    if (p2) activePrimitives.push(p2);
  }

  // 8. INTERACTIVE HANDLERS
  // Create an invisible target plate for reliable hit-testing
  const hitPlaneGeo = new PlaneGeometry(3, 3);
  const hitPlaneMat = new MeshStandardNodeMaterial({
    visible: false,
    depthWrite: false
  });
  const hitPlane = new Mesh(hitPlaneGeo, hitPlaneMat);
  hitPlane.position.set(0, 0, 0.4);
  root.add(hitPlane);

  let hoverTl = null;

  root.userData.handlers = {
    pointerover: () => {
      // "preset:rise-in (subtle, 0.15 scene units)"
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(meshContainer.position, {
        y: 0.15,
        duration: 0.4,
        ease: 'power2.out'
      });
      hoverTl.to(meshContainer.rotation, {
        y: 0.2,
        duration: 0.4,
        ease: 'power2.out'
      }, 0);
    },
    pointerout: () => {
      if (hoverTl) hoverTl.kill();
      hoverTl = gsap.timeline();
      hoverTl.to(meshContainer.position, {
        y: 0,
        duration: 0.4,
        ease: 'power2.out'
      });
      hoverTl.to(meshContainer.rotation, {
        y: 0,
        duration: 0.4,
        ease: 'power2.out'
      }, 0);
    },
    click: () => {
      // Emit the requested transition event
      ctx.emit('hub-features.select', { id: config.id });

      // Punchy response scale-down-then-settle
      const clickTl = gsap.timeline();
      clickTl.to(meshContainer.scale, { x: 0.9, y: 0.9, z: 0.9, duration: 0.08, ease: 'power2.out' });
      clickTl.to(meshContainer.scale, { x: 1, y: 1, z: 1, duration: 0.4, ease: 'back.out(2)' });
      activeTimelines.push(clickTl);
    }
  };

  // 9. CLEANUP INTERFACE
  root.userData.cleanup = () => {
    if (hoverTl) hoverTl.kill();
    activeTimelines.forEach((t) => t.kill());
    activePrimitives.forEach((p) => {
      if (typeof p.cleanup === 'function') p.cleanup();
    });

    // Geometries
    backdropGeo.dispose();
    shadowGeo.dispose();
    captionBgGeo.dispose();
    pipGeo.dispose();
    hitPlaneGeo.dispose();

    // Materials
    backdropMat.dispose();
    shadowMat.dispose();
    captionBgMat.dispose();
    pipMat.dispose();
    hitPlaneMat.dispose();
  };

  return root;
}
